using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long double n, R, r;
    if (!(cin >> n >> R >> r)) return 0;

    const long double pi = acosl(-1.0L);
    const long double eps = 1e-9L;
    long double ratio = r / (R - r);

    if (ratio <= 1.0L && n * asinl(ratio) <= pi + eps)
        cout << "YES\n";
    else
        cout << "NO\n";

    return 0;
}

